 bad=f.state;bad.policies.erase(first);check(!bad_read(bad).ok);bad=f.state;bad.policies.find(first)->registration_fact_id=approval;check(!bad_read(bad).ok);bad=f.state;bad.policies.find(first)->issued_tick=1;check(!bad_read(bad).ok);
